window.P1_UNITS = [
{ n:1, title:"FRIENDS AND FAMILY", classes:"1\u20137", level:"The Gerund Grasslands", icon:"grass", color:"#6a9e3c", theme:"Personality, friendship and family structures",
  overview:{
    intro:"This unit is about the people closest to you \u2014 who they are, how you resemble them, and how you deal with them. At B2 the challenge is no longer listing family members, but describing relationships with precision: how people behave, why they clash, and what holds them together.",
    goals:["Describe personality and family relationships with natural, specific vocabulary.","Use the gerund confidently after common verbs and after every preposition.","Explain and define ideas using noun clauses after \u2018be\u2019."],
    outcome:"By the end you can describe a family member in detail, explain who you take after and why, and use at least three verb + gerund patterns without hesitating."
  },
  vocab:[
    {term:"to get along (with)", pos:"phrasal verb", def:"to have a friendly, easy relationship with someone.",
     use:"Use \u2018with\u2019 before the person: get along WITH your sister. On its own it describes the pair: \u2018We get along.\u2019 In British English \u2018get on with\u2019 is more common.",
     examples:["I get along with my brother far better now that we live apart.","They\u2019ve never really got along, but they stay polite at family dinners."],
     colloc:"get along well \u00b7 get along fine \u00b7 not get along at all"},
    {term:"close-knit", pos:"adjective", def:"(of a family or group) bound together by strong, warm ties.",
     use:"Only used before a noun: a close-knit family / community / team. It is always positive.",
     examples:["We\u2019re a close-knit family \u2014 nobody makes a big decision alone.","She grew up in a close-knit neighbourhood where everyone knew her name."],
     colloc:"a close-knit family \u00b7 a close-knit community \u00b7 a close-knit team"},
    {term:"to take after", pos:"phrasal verb", def:"to resemble an older relative in looks or in character.",
     use:"Only for relatives, and only for older ones \u2014 you take after a parent, never after a friend. Never separable: \u2018take after him\u2019, not \u2018take him after\u2019.",
     examples:["He takes after his grandfather \u2014 same laugh, same stubbornness.","I take after my mother in looks but after my father in temperament."],
     colloc:"take after your mother / father \u00b7 really take after someone"},
    {term:"easygoing", pos:"adjective", def:"relaxed and not easily worried or annoyed.",
     use:"A compliment about temperament. Compare \u2018laid-back\u2019 (very similar, more informal) and \u2018lazy\u2019 (negative, not a synonym).",
     examples:["My dad is so easygoing that nothing ever seems to bother him.","She\u2019s easygoing about most things, but not about punctuality."],
     colloc:"an easygoing person \u00b7 fairly easygoing \u00b7 easygoing about something"},
    {term:"to bond (with)", pos:"verb", def:"to form a close emotional connection with someone.",
     use:"Often used about a shared experience creating the connection: they bonded OVER football.",
     examples:["The cousins bonded over a shared love of cooking.","New parents need time to bond with the baby."],
     colloc:"bond with someone \u00b7 bond over something \u00b7 a strong bond"},
    {term:"sibling rivalry", pos:"noun phrase", def:"competition or jealousy between brothers and sisters.",
     use:"A slightly formal, almost psychological term \u2014 useful in discussions and writing rather than casual chat.",
     examples:["A bit of sibling rivalry is normal; constant fighting isn\u2019t.","Their sibling rivalry faded once they both left home."],
     colloc:"intense sibling rivalry \u00b7 a healthy sibling rivalry"} ],
  grammar:[
    {name:"Verbs followed by gerunds", short:"enjoy, avoid, mind, keep + -ing \u2014 and after every preposition.",
     rule:"Some verbs are always followed by the -ing form rather than the infinitive: enjoy, avoid, mind, keep, finish, can\u2019t stand, feel like, suggest, consider. In addition, any verb that follows a preposition takes -ing.",
     form:["Verb + -ing: enjoy spending, avoid arguing, keep interrupting, finish talking.","Adjective + preposition + -ing: good at listening, tired of waiting, interested in learning.","Verb + preposition + -ing: insist on paying, look forward to seeing, apologise for being late."],
     notes:["\u2018Feel like\u2019 means \u2018want\u2019 and always takes -ing: \u2018I feel like going out\u2019, never \u2018feel like to go\u2019.","\u2018Look forward to\u2019 ends in the preposition \u2018to\u2019, so it takes -ing: \u2018looking forward to meeting you\u2019.","To make a gerund negative, put \u2018not\u2019 in front: \u2018I enjoy not having plans on Sunday.\u2019"],
     examples:["I enjoy spending time with my cousins at the weekend.","She can\u2019t stand arguing over nothing.","They\u2019re good at getting along with everyone."],
     watch:"After a preposition, English always uses -ing \u2014 \u2018interested in learning\u2019, never \u2018interested in to learn\u2019."},
    {name:"Noun clauses after \u2018be\u2019", short:"The problem is that\u2026 / What matters is\u2026",
     rule:"A whole clause can work as a noun. Placed after the verb \u2018be\u2019, it defines or explains the subject: \u2018The problem is that we never listen.\u2019",
     form:["Noun + be + that-clause: The truth is that we take after our mother.","What-clause + be + noun/clause: What matters is that we stay close.","The reason\u2026 + be + that-clause: The reason I called is that I miss you."],
     notes:["\u2018That\u2019 can be dropped in speech: \u2018The truth is we take after her.\u2019","When the subject is a \u2018what\u2019-clause, the verb is singular: \u2018What worries me is the silence.\u2019","Word order inside the clause is statement order \u2014 no inversion: \u2018The question is where he went\u2019, not \u2018where did he go\u2019."],
     examples:["The truth is that we take after our mother.","What matters is that we stay close.","The reason I called is that I miss you."],
     watch:"Say \u2018The reason is THAT\u2026\u2019, not \u2018The reason is BECAUSE\u2026\u2019 \u2014 that repeats the idea twice."} ],
  speaking:[
    {kind:"Role-play", text:"In pairs, two siblings plan a surprise party for a parent but can\u2019t agree on anything \u2013 practise getting along and compromising."},
    {kind:"Debate", text:"This house believes friends can be closer than family. Argue for or against."},
    {kind:"Pair work", text:"Describe someone in your family you take after \u2013 in looks and in personality."} ],
  tips:[
    "After a preposition, always use the -ing form: \u2018good at cooking\u2019, \u2018interested in learning\u2019.",
    "\u2018Enjoy, avoid, mind, finish, keep\u2019 are never followed by \u2018to\u2019 \u2013 say \u2018enjoy reading\u2019, not \u2018enjoy to read\u2019.",
    "Common slip: \u2018The reason is that\u2026\u2019, not \u2018The reason is because\u2026\u2019."],
  quiz:{q:"I really enjoy ___ time with my family at weekends.", options:["spending","to spend","spend"], answer:0, explain:"After \u2018enjoy\u2019 we use the gerund: \u2018enjoy spending\u2019."} },

{ n:2, title:"MISTAKES AND MYSTERIES", classes:"8\u201314", level:"The Creeper Caverns", icon:"creeper", color:"#3f8f2f", theme:"Past obligation, speculation and unsolved mysteries",
  overview:{
    intro:"This unit is about the past you cannot change and the past you cannot explain. You will learn to talk about what you had to do, what you should have done, and what might, must or can\u2019t have happened \u2014 the language of regret, blame and speculation.",
    goals:["Talk about past obligation and criticise past actions politely.","Speculate about the past with modal verbs and different degrees of certainty.","Describe mysteries, evidence and conclusions with precise vocabulary."],
    outcome:"By the end you can retell an unsolved event and offer three theories about it, each with a different level of certainty."
  },
  vocab:[
    {term:"eerie", pos:"adjective", def:"strange and frightening in a mysterious way.",
     use:"Describes atmosphere rather than people: an eerie silence, an eerie glow. Stronger and stranger than \u2018creepy\u2019, which is more personal.",
     examples:["There was an eerie silence in the house after everyone left.","The fog gave the whole street an eerie feel."],
     colloc:"an eerie silence \u00b7 an eerie atmosphere \u00b7 eerily quiet"},
    {term:"to figure out", pos:"phrasal verb", def:"to understand or solve something after thinking about it.",
     use:"Separable: figure out the answer / figure it out. Slightly informal; \u2018work out\u2019 is the British equivalent.",
     examples:["It took us hours to figure out how he\u2019d got in.","I still can\u2019t figure it out."],
     colloc:"figure out what happened \u00b7 figure it out \u00b7 finally figure something out"},
    {term:"clue", pos:"noun", def:"a piece of information that helps solve a mystery.",
     use:"You give, find or follow a clue. \u2018Not have a clue\u2019 is a common idiom meaning \u2018have no idea\u2019.",
     examples:["The only clue was a muddy footprint by the door.","Honestly, I haven\u2019t got a clue what happened."],
     colloc:"a vital clue \u00b7 find / leave a clue \u00b7 not have a clue"},
    {term:"to jump to conclusions", pos:"idiom", def:"to decide something too quickly, without all the facts.",
     use:"Almost always a criticism or a warning: \u2018Let\u2019s not jump to conclusions.\u2019",
     examples:["Don\u2019t jump to conclusions \u2014 we haven\u2019t heard his side yet.","She jumped to conclusions and accused the wrong person."],
     colloc:"jump to conclusions \u00b7 let\u2019s not jump to conclusions"},
    {term:"baffling", pos:"adjective", def:"impossible to understand; very confusing.",
     use:"Describes the thing, not the person: a baffling case. The person is \u2018baffled\u2019.",
     examples:["The disappearance of the plane remains baffling.","Police were baffled by the lack of evidence."],
     colloc:"a baffling mystery \u00b7 utterly baffling \u00b7 be baffled by something"},
    {term:"culprit", pos:"noun", def:"the person \u2014 or thing \u2014 responsible for a crime or problem.",
     use:"Also used humorously for the cause of a small problem: \u2018The culprit was a loose wire.\u2019",
     examples:["The culprit turned out to be a neighbour\u2019s cat.","Investigators are still looking for the culprit."],
     colloc:"catch the culprit \u00b7 the real culprit \u00b7 the likely culprit"} ],
  grammar:[
    {name:"Past modals of obligation", short:"had to / should have / was supposed to.",
     rule:"Different structures express different relationships to a past duty: whether it happened, whether it was necessary, and whether you regret it.",
     form:["had to + verb = a real past obligation that was fulfilled: We had to leave early.","didn\u2019t have to + verb = no obligation existed (and usually it didn\u2019t happen).","should / ought to have + past participle = criticism or regret about the past.","was / were supposed to + verb = an expectation that was probably not met."],
     notes:["\u2018Didn\u2019t have to\u2019 and \u2018shouldn\u2019t have\u2019 are very different: \u2018You didn\u2019t have to pay\u2019 (it wasn\u2019t necessary) vs \u2018You shouldn\u2019t have paid\u2019 (it was a mistake).","\u2018Must\u2019 has no past form for obligation \u2014 use \u2018had to\u2019.","\u2018Was supposed to\u2019 strongly implies the thing did NOT happen: \u2018She was supposed to lock the door\u2019 \u2014 and she didn\u2019t."],
     examples:["We had to leave before midnight.","You should have told me the truth.","She was supposed to lock the door."],
     watch:"After \u2018should have\u2019 use a past participle, not a past simple: \u2018should have gone\u2019, never \u2018should have went\u2019."},
    {name:"Modals for degrees of certainty about the past", short:"must have / might have / can\u2019t have.",
     rule:"To draw a conclusion about the past from present evidence, use a modal + have + past participle. The modal you choose shows how sure you are.",
     form:["must have + p.p. = you are almost certain it happened.","might / may / could have + p.p. = it is possible.","can\u2019t / couldn\u2019t have + p.p. = you are almost certain it did NOT happen."],
     notes:["The negative of \u2018must have\u2019 in this meaning is \u2018can\u2019t have\u2019, not \u2018mustn\u2019t have\u2019.","\u2018Could have\u2019 has two meanings: possibility (\u2018He could have missed the bus\u2019) and unrealised ability (\u2018I could have helped, but nobody asked\u2019).","In speech, \u2018have\u2019 reduces to /\u0259v/ \u2014 which is why learners write the incorrect \u2018must of\u2019."],
     examples:["He must have forgotten his keys.","It can\u2019t have been the cat.","They might have taken the wrong turn."],
     watch:"Write \u2018must have\u2019, never \u2018must of\u2019 \u2014 they sound identical but only one is English."} ],
  speaking:[
    {kind:"Role-play", text:"Two detectives at a crime scene disagree about what must have happened and what can\u2019t have happened."},
    {kind:"Debate", text:"This house believes some mysteries are better left unsolved. Agree or disagree."},
    {kind:"Pair work", text:"Tell a partner about a time you jumped to conclusions and got it completely wrong."} ],
  tips:[
    "\u2018must have + past participle\u2019 = near-certain it happened; \u2018can\u2019t have\u2019 = certain it didn\u2019t.",
    "\u2018should have + p.p.\u2019 expresses regret or criticism: \u2018I should have studied more.\u2019",
    "Common slip: say \u2018must have gone\u2019, not \u2018must have went\u2019."],
  quiz:{q:"The lights are off \u2013 they ___ already gone home.", options:["must have","should have","can\u2019t have"], answer:0, explain:"\u2018Must have + past participle\u2019 expresses near-certainty about the past."} },

{ n:3, title:"EXPLORING NEW CITIES", classes:"15\u201321", level:"The Relative-Clause Ravine", icon:"compass", color:"#5a7d99", theme:"Describing places, contrast and city vs. small-town life",
  overview:{
    intro:"Describing a place well means adding information without starting a new sentence every time. This unit gives you relative clauses to pack detail into one sentence, the correct order for stacked adjectives, and linkers to admit a drawback while defending your opinion.",
    goals:["Describe cities, neighbourhoods and landmarks with vivid, precise adjectives.","Use defining and non-defining relative clauses accurately, with correct punctuation.","Concede and contrast using despite, although and however."],
    outcome:"By the end you can give a two-minute description of a city you know, using at least three relative clauses and two contrast linkers."
  },
  vocab:[
    {term:"bustling", pos:"adjective", def:"full of energetic and noisy activity.",
     use:"Positive \u2014 it suggests life and energy, not stress. Used before nouns: a bustling market.",
     examples:["The old town is a bustling maze of cafes and stalls.","By eight in the morning the port is already bustling."],
     colloc:"a bustling market \u00b7 a bustling city centre \u00b7 bustling with people"},
    {term:"landmark", pos:"noun", def:"a famous building or place that is easily recognised.",
     use:"Also used figuratively for an important moment: \u2018a landmark decision\u2019.",
     examples:["The cathedral is the city\u2019s best-known landmark.","We used the tower as a landmark to find our way back."],
     colloc:"a famous landmark \u00b7 a historic landmark \u00b7 a landmark building"},
    {term:"to soak up (the atmosphere)", pos:"phrasal verb", def:"to fully enjoy and absorb the feeling of a place.",
     use:"Used with atmosphere, sun, culture. Suggests slow, unhurried enjoyment rather than sightseeing.",
     examples:["We sat in the square for an hour just soaking up the atmosphere.","Skip the museums and soak up the street life instead."],
     colloc:"soak up the atmosphere \u00b7 soak up the sun \u00b7 soak up the culture"},
    {term:"off the beaten track", pos:"idiom", def:"away from the places tourists usually visit.",
     use:"Usually positive, implying authenticity. American English often says \u2018off the beaten path\u2019.",
     examples:["The best food is always off the beaten track.","We stayed in a village well off the beaten track."],
     colloc:"somewhere off the beaten track \u00b7 well off the beaten track"},
    {term:"sprawling", pos:"adjective", def:"spreading out over a large, untidy area.",
     use:"Slightly negative or neutral \u2014 it suggests size without planning.",
     examples:["The city is a sprawling mass of low houses and highways.","Sprawling suburbs have swallowed the old farmland."],
     colloc:"a sprawling city \u00b7 sprawling suburbs \u00b7 urban sprawl (noun)"},
    {term:"quaint", pos:"adjective", def:"attractively old-fashioned and charming.",
     use:"Careful: applied to people or ideas it can sound patronising. Safest for buildings and villages.",
     examples:["It\u2019s a quaint little town with cobbled streets.","The hotel was quaint rather than comfortable."],
     colloc:"a quaint village \u00b7 quaint cottages \u00b7 rather quaint"} ],
  grammar:[
    {name:"Defining & non-defining relative clauses", short:"Which one needs commas \u2014 and which forbids \u2018that\u2019.",
     rule:"A defining relative clause identifies which person or thing you mean and is essential; a non-defining clause adds extra information about something already identified.",
     form:["Defining (no commas): The guide who showed us around was brilliant.","Non-defining (commas, never \u2018that\u2019): Bogot\u00e1, which sits high in the Andes, is chilly.","Place / time / possession: where, when, whose \u2014 the street where I grew up."],
     notes:["In a defining clause you can drop the pronoun when it is the object: \u2018the city (that) we visited\u2019. You can never drop it in a non-defining clause.","\u2018That\u2019 is only possible in defining clauses.","A preposition can move to the end in speech: \u2018the district that we stayed in\u2019 (formal: \u2018in which we stayed\u2019)."],
     examples:["The neighbourhood where I grew up has changed completely.","Bogot\u00e1, which sits high in the Andes, is chilly all year.","The guide who showed us around was brilliant."],
     watch:"If you can remove the clause and still know who or what you mean, it needs commas \u2014 and \u2018which\u2019, not \u2018that\u2019."},
    {name:"Order of modifiers", short:"opinion \u2192 size \u2192 age \u2192 shape \u2192 colour \u2192 origin \u2192 material.",
     rule:"When several adjectives modify one noun, English uses a fixed order. Native speakers never think about it, but breaking it sounds instantly wrong.",
     form:["opinion \u2192 size \u2192 age \u2192 shape \u2192 colour \u2192 origin \u2192 material \u2192 NOUN.","a lovely (opinion) little (size) old (age) stone (material) bridge.","a huge modern glass tower \u00b7 a charming narrow cobbled street."],
     notes:["Three adjectives before a noun is usually the practical maximum; beyond that, split the sentence.","Adjectives of the same type are joined with \u2018and\u2019 or commas: \u2018a red and white facade\u2019.","Nouns used as modifiers come last, right before the head noun: \u2018an old stone bridge\u2019."],
     examples:["a lovely little old stone bridge","a huge modern glass tower","a charming narrow cobbled street"],
     watch:"Size comes before age: \u2018a big old house\u2019, not \u2018an old big house\u2019."},
    {name:"Connecting contrasting ideas", short:"despite / although / however \u2014 what follows each one.",
     rule:"All three express contrast, but they are followed by different structures, and that is where mistakes happen.",
     form:["despite / in spite of + noun or -ing: Despite the traffic, we loved it.","although / even though / though + subject + verb: Although it rained, we explored.","however / on the other hand + full sentence, after a semicolon or full stop."],
     notes:["To use \u2018despite\u2019 with a clause, add \u2018the fact that\u2019: \u2018despite the fact that it rained\u2019.","\u2018However\u2019 is not a conjunction \u2014 it cannot join two clauses with only a comma.","\u2018Even though\u2019 is stronger than \u2018although\u2019; \u2018though\u2019 can also come at the end in speech: \u2018It was expensive, though.\u2019"],
     examples:["Despite the traffic, we loved every minute.","Although it rained all weekend, we explored the old town.","It\u2019s expensive; however, it\u2019s worth every peso."],
     watch:"Never write \u2018despite it rained\u2019 \u2014 \u2018despite\u2019 takes a noun or -ing, never a clause."} ],
  speaking:[
    {kind:"Role-play", text:"A tour guide shows a visitor around your city, pointing out landmarks and hidden spots off the beaten track."},
    {kind:"Debate", text:"This house believes city life is better than small-town life. Argue for or against."},
    {kind:"Pair work", text:"Describe a place you love using at least two relative clauses and one contrast linker."} ],
  tips:[
    "Non-defining clauses need commas and never use \u2018that\u2019 \u2013 use \u2018which\u2019 or \u2018who\u2019.",
    "\u2018Despite\u2019 and \u2018in spite of\u2019 take a noun or -ing, not a clause: \u2018despite the rain\u2019, not \u2018despite it rained\u2019.",
    "Common slip: keep adjective order natural \u2013 \u2018a big old house\u2019, not \u2018an old big house\u2019."],
  quiz:{q:"Medell\u00edn, ___ is known as the City of Eternal Spring, has a mild climate.", options:["which","that","where"], answer:0, explain:"Non-defining clauses (set off by commas) use \u2018which\u2019, never \u2018that\u2019."} },

{ n:4, title:"EARLY BIRDS AND NIGHT OWLS", classes:"22\u201328", level:"The Reduced-Clause Bedrock", icon:"bed", color:"#b23b52", theme:"Sleep, daily routines and time-of-day preferences",
  overview:{
    intro:"Routines produce long, repetitive sentences \u2014 \u2018When I get up, I make coffee, and after I make coffee, I check my phone.\u2019 This unit teaches you to compress them into shorter, more fluent English, and to state the reasons and conditions behind your habits.",
    goals:["Talk about sleep, energy and daily routines with natural expressions.","Shorten time clauses to participle phrases when the subject is shared.","Give reasons and set conditions with because, since, unless and as long as."],
    outcome:"By the end you can describe your ideal day using at least three reduced time clauses and explain two conditions for your best sleep."
  },
  vocab:[
    {term:"to be a morning person", pos:"expression", def:"to feel most energetic and alert early in the day.",
     use:"The opposite is \u2018a night owl\u2019. Very common in the negative: \u2018I\u2019m not a morning person.\u2019",
     examples:["I\u2019m not a morning person \u2014 don\u2019t call me before ten.","She\u2019s such a morning person that she runs at five a.m."],
     colloc:"a real morning person \u00b7 not a morning person \u00b7 an early bird"},
    {term:"to hit the sack", pos:"idiom (informal)", def:"to go to bed.",
     use:"Casual and friendly \u2014 fine with friends, out of place in writing. \u2018Hit the hay\u2019 is the same idea.",
     examples:["I\u2019m exhausted; I\u2019m going to hit the sack.","We hit the sack early and were up at dawn."],
     colloc:"hit the sack early \u00b7 time to hit the sack"},
    {term:"to sleep in", pos:"phrasal verb", def:"to sleep later than usual in the morning, by choice.",
     use:"Different from \u2018oversleep\u2019, which is accidental and usually a problem.",
     examples:["On Sundays I sleep in until eleven.","I overslept and missed the bus \u2014 that\u2019s not the same as sleeping in."],
     colloc:"sleep in late \u00b7 get to sleep in \u00b7 sleep in on weekends"},
    {term:"groggy", pos:"adjective", def:"dazed and sluggish after waking or too little sleep.",
     use:"Temporary state, usually right after waking or after medicine. Not a personality trait.",
     examples:["I felt groggy for the first hour after the alarm.","Too much sleep can leave you just as groggy as too little."],
     colloc:"feel groggy \u00b7 wake up groggy \u00b7 a bit groggy"},
    {term:"to wind down", pos:"phrasal verb", def:"to relax and calm down, especially at the end of the day.",
     use:"Note the pronunciation: \u2018wind\u2019 rhymes with \u2018mind\u2019. The opposite is \u2018wind up\u2019 (make someone tense).",
     examples:["I need an hour to wind down before I can sleep.","A hot shower helps me wind down after work."],
     colloc:"wind down after work \u00b7 a wind-down routine \u00b7 help you wind down"},
    {term:"productive", pos:"adjective", def:"getting a lot done; achieving good results.",
     use:"Describes people, days, meetings and habits. The noun is \u2018productivity\u2019.",
     examples:["My most productive hours are between six and nine in the morning.","It was a productive meeting for once."],
     colloc:"a productive day \u00b7 highly productive \u00b7 productive hours"} ],
  grammar:[
    {name:"Reduced time clauses", short:"While I was cooking \u2192 While cooking.",
     rule:"When the time clause and the main clause share the same subject, you can delete the subject and use the -ing form of the verb after before, after, when, while or since.",
     form:["Before going to bed, I read for a while.","After finishing work, she goes for a run.","While waiting for the bus, he answered his emails."],
     notes:["The reduction is only possible when both subjects are identical. \u2018While I was cooking, my brother called\u2019 cannot be reduced.","With \u2018after\u2019 you may also use the perfect form for a clear sequence: \u2018After having finished, she left.\u2019","A reduced clause at the start of a sentence is followed by a comma."],
     examples:["Before going to bed, I always switch off my phone.","After finishing work, she goes straight to the gym.","When feeling tired, take a short break rather than more coffee."],
     watch:"Never reduce when the subjects differ \u2014 \u2018While cooking, the phone rang\u2019 says the phone was cooking."},
    {name:"Clauses of reason and condition", short:"because / since / as \u2014 if / unless / as long as.",
     rule:"Reason clauses explain why; condition clauses state what must be true for the result to happen. Both attach to the main clause with a subordinating conjunction.",
     form:["Reason: because / since / as + subject + verb.","Condition: if / unless / as long as / provided that + subject + verb.","Either clause can come first; put a comma after it when it does."],
     notes:["\u2018Since\u2019 and \u2018as\u2019 introduce a reason the listener already knows; \u2018because\u2019 gives new, important information.","\u2018Unless\u2019 = \u2018if\u2026 not\u2019, so it is already negative.","In condition clauses about the future, use the present tense: \u2018As long as it stays quiet, I\u2019ll finish tonight.\u2019"],
     examples:["Since I\u2019m an early bird, I schedule my meetings in the morning.","Unless I sleep eight hours, I\u2019m groggy all day.","As long as it\u2019s quiet, I can focus anywhere."],
     watch:"Don\u2019t add a second negative after \u2018unless\u2019: \u2018unless I sleep\u2019, not \u2018unless I don\u2019t sleep\u2019."} ],
  speaking:[
    {kind:"Role-play", text:"A sleep coach advises a client who can\u2019t fall asleep \u2013 give and respond to routine advice."},
    {kind:"Debate", text:"This house believes the world is designed for morning people. Agree or disagree."},
    {kind:"Pair work", text:"Compare your ideal daily routine with a partner\u2019s \u2013 who is the real early bird?"} ],
  tips:[
    "You can only reduce a time clause when both clauses have the same subject.",
    "\u2018Unless\u2019 already means \u2018if\u2026 not\u2019 \u2013 don\u2019t add a second negative after it.",
    "Common slip: \u2018before / after + -ing\u2019, not \u2018+ to\u2019: \u2018after eating\u2019, not \u2018after to eat\u2019."],
  quiz:{q:"___ going to bed, I always switch off my phone.", options:["Before","During","Unless"], answer:0, explain:"A reduced time clause uses before / after / while + -ing: \u2018Before going to bed\u2019."} },

{ n:5, title:"COMMUNICATION", classes:"29\u201335", level:"The Infinitive Village", icon:"emerald", color:"#1f9d57", theme:"Personality types and commenting on communication behaviour",
  overview:{
    intro:"This unit is about how people talk \u2014 the blunt, the tactful, the ones who never get to the point \u2014 and about how you judge that behaviour out loud. The structure \u2018It\u2019s + adjective + to\u2026\u2019 lets you comment on behaviour without attacking a person.",
    goals:["Describe communication styles and personality with accurate adjectives.","Comment on behaviour using \u2018It\u2019s + adjective / noun + infinitive\u2019.","Use gerunds as subjects to make general statements."],
    outcome:"By the end you can describe your own communication style and give three pieces of advice using impersonal \u2018It\u2019s\u2026 to\u2026\u2019 structures."
  },
  vocab:[
    {term:"outspoken", pos:"adjective", def:"expressing strong opinions openly, even when others disagree.",
     use:"Neutral to positive \u2014 it suggests courage. \u2018Blunt\u2019 and \u2018tactless\u2019 are the negative versions.",
     examples:["She\u2019s an outspoken critic of the new policy.","He\u2019s outspoken, but he\u2019s never cruel."],
     colloc:"an outspoken critic \u00b7 outspoken about something \u00b7 remarkably outspoken"},
    {term:"to beat around the bush", pos:"idiom", def:"to avoid saying something directly.",
     use:"Nearly always a criticism, often as an instruction: \u2018Stop beating around the bush.\u2019",
     examples:["Stop beating around the bush and tell me what happened.","He beat around the bush for ten minutes before mentioning the money."],
     colloc:"stop beating around the bush \u00b7 no point beating around the bush"},
    {term:"tactful", pos:"adjective", def:"careful not to say things that upset people.",
     use:"About delivery, not honesty \u2014 you can be tactful and truthful at once. The noun is \u2018tact\u2019.",
     examples:["That was a tactful way of saying no.","She\u2019s tactful enough to criticise without offending."],
     colloc:"a tactful reply \u00b7 be tactful about something \u00b7 show tact"},
    {term:"to come across (as)", pos:"phrasal verb", def:"to give a particular impression to other people.",
     use:"About perception, not reality \u2014 which is why it pairs with \u2018although in fact\u2026\u2019.",
     examples:["He comes across as arrogant, although he\u2019s actually shy.","Try to come across as confident in the interview."],
     colloc:"come across as rude / friendly \u00b7 come across well"},
    {term:"reserved", pos:"adjective", def:"quiet and not showing feelings or opinions easily.",
     use:"Neutral, unlike \u2018cold\u2019 or \u2018unfriendly\u2019. Describes temperament, not mood.",
     examples:["He\u2019s reserved at first, but very warm once you know him.","In meetings she stays reserved and listens."],
     colloc:"quite reserved \u00b7 a reserved manner \u00b7 reserved by nature"},
    {term:"to get straight to the point", pos:"idiom", def:"to say the main thing at once, with no extra talk.",
     use:"Positive in professional contexts; the direct opposite of \u2018beat around the bush\u2019.",
     examples:["I\u2019ll get straight to the point: we need the report by Friday.","She always gets straight to the point in meetings."],
     colloc:"get straight to the point \u00b7 come to the point"} ],
  grammar:[
    {name:"It\u2019s + adjective / noun + infinitive", short:"Comment on behaviour without blaming a person.",
     rule:"\u2018It\u2019 stands in for a later infinitive phrase, letting you evaluate an action in general: \u2018It\u2019s rude to interrupt.\u2019 To name the person, add \u2018for someone\u2019 or, with adjectives of character, \u2018of someone\u2019.",
     form:["It\u2019s + adjective + to + verb: It\u2019s important to listen carefully.","It\u2019s + a / an + noun + to + verb: It\u2019s a mistake to beat around the bush.","It\u2019s + adjective + FOR someone + to + verb: It\u2019s hard for him to say sorry.","It\u2019s + adjective + OF someone + to + verb: It was kind of you to call."],
     notes:["Use \u2018of\u2019 when the adjective judges the person (kind, rude, generous); \u2018for\u2019 when it judges the difficulty (hard, easy, important).","The same idea can be turned round with a gerund subject: \u2018Interrupting people is rude.\u2019","The gerund version sounds more general and more written; the \u2018It\u2019s\u2026\u2019 version is more common in speech."],
     examples:["It\u2019s important to listen carefully before replying.","It\u2019s a mistake to beat around the bush at work.","Being tactful takes practice."],
     watch:"After \u2018It\u2019s + adjective\u2019 use the infinitive, not -ing: \u2018It\u2019s easy to say sorry\u2019, not \u2018It\u2019s easy saying sorry\u2019."},
    {name:"Gerunds as subjects", short:"Listening is a skill.",
     rule:"An -ing form can act as the subject of a sentence, naming an activity in general. It always takes a singular verb.",
     form:["Gerund + singular verb: Listening carefully saves time.","Negative: Not answering messages is rude.","With an object: Interrupting people during meetings annoys everyone."],
     notes:["Never use an infinitive as the subject in everyday English: \u2018To listen is a skill\u2019 sounds literary or biblical.","Two gerund subjects joined by \u2018and\u2019 take a plural verb: \u2018Listening and asking questions help.\u2019","Gerund subjects are common in written arguments and in advice."],
     examples:["Being tactful takes practice.","Interrupting people is the fastest way to lose an argument.","Not saying what you mean creates confusion."],
     watch:"Keep the verb singular: \u2018Listening is important\u2019, not \u2018Listening are important\u2019."} ],
  speaking:[
    {kind:"Role-play", text:"A manager gives feedback to an employee who is too blunt with clients \u2013 stay tactful throughout."},
    {kind:"Debate", text:"This house believes it\u2019s always better to be direct than polite. Argue for or against."},
    {kind:"Pair work", text:"Describe your communication style \u2013 are you outspoken or reserved? Give examples."} ],
  tips:[
    "After \u2018It\u2019s + adjective\u2019, use the infinitive: \u2018It\u2019s easy to say sorry.\u2019",
    "When an action is the subject of a sentence, use the -ing form: \u2018Listening is a skill.\u2019",
    "Common slip: \u2018It\u2019s important to be\u2026\u2019, not \u2018It\u2019s important being\u2026\u2019."],
  quiz:{q:"It\u2019s not always easy ___ what you really think.", options:["to say","saying","say"], answer:0, explain:"After \u2018It\u2019s + adjective\u2019 we use the infinitive: \u2018easy to say\u2019."} },

{ n:6, title:"WHAT\u2019S THE REAL STORY?", classes:"36\u201342", level:"The Perfect-Tense Chest", icon:"chest", color:"#8a5a2a", theme:"Rumours, journalism and unravelling a story",
  overview:{
    intro:"News language lives on the border between past and present: what has just happened, what happened last night, and what had already happened before that. This unit sorts out those tenses so you can report events clearly and say exactly when they belong.",
    goals:["Talk about news, rumours and reliability with journalistic vocabulary.","Choose correctly between present perfect and simple past.","Order past events with the past perfect and time adverbs."],
    outcome:"By the end you can report a story in three tenses \u2014 what had happened before, what happened, and what has happened since."
  },
  vocab:[
    {term:"to break a story", pos:"expression", def:"to be the first to report important news.",
     use:"Also used intransitively about the news itself: \u2018The story broke last night.\u2019",
     examples:["A local paper broke the story before the national media.","The scandal broke just after the election."],
     colloc:"break a story \u00b7 the story broke \u00b7 breaking news"},
    {term:"rumour", pos:"noun", def:"information passed around that may not be true.",
     use:"Common patterns: \u2018there\u2019s a rumour that\u2026\u2019, \u2018rumour has it that\u2026\u2019. Spelled \u2018rumor\u2019 in American English.",
     examples:["There\u2019s a rumour that the factory is closing.","Rumour has it they\u2019ve already signed the deal."],
     colloc:"spread a rumour \u00b7 deny a rumour \u00b7 rumour has it"},
    {term:"to get to the bottom of", pos:"idiom", def:"to discover the real truth about something.",
     use:"Followed by a noun or a wh-clause: get to the bottom of it / of what happened.",
     examples:["We need to get to the bottom of this before we accuse anyone.","It took months to get to the bottom of the story."],
     colloc:"get to the bottom of it \u00b7 get to the bottom of the matter"},
    {term:"biased", pos:"adjective", def:"unfairly favouring one side; not neutral.",
     use:"Take the preposition \u2018towards\u2019 or \u2018against\u2019. The noun is \u2018bias\u2019; the neutral opposite is \u2018impartial\u2019.",
     examples:["The report was clearly biased against small businesses.","Everyone is biased \u2014 good journalism just admits it."],
     colloc:"biased against / towards \u00b7 politically biased \u00b7 media bias"},
    {term:"eyewitness", pos:"noun", def:"a person who personally saw an event happen.",
     use:"Stronger than \u2018witness\u2019 because it stresses seeing. Common as a modifier: an eyewitness account.",
     examples:["Two eyewitnesses gave completely different versions.","Eyewitness accounts are famously unreliable."],
     colloc:"an eyewitness account \u00b7 according to eyewitnesses"},
    {term:"to blow out of proportion", pos:"idiom", def:"to make something seem far more important than it is.",
     use:"Usually passive: \u2018It\u2019s been blown out of proportion.\u2019 A common way to defend someone.",
     examples:["The whole incident was blown out of proportion by the press.","Don\u2019t blow it out of proportion \u2014 it was one comment."],
     colloc:"blown out of all proportion \u00b7 blow something out of proportion"} ],
  grammar:[
    {name:"Present perfect vs. simple past", short:"Connected to now, or finished and dated.",
     rule:"Use the present perfect for past actions with a present result or inside unfinished time; use the simple past for finished actions at a definite past time.",
     form:["Present perfect: have / has + past participle \u2014 Reporters have uncovered new evidence.","Simple past: The story broke last night.","Unfinished time: this week, today, so far, ever, never \u2192 present perfect."],
     notes:["A definite past time expression (yesterday, in 2019, last night) forces the simple past.","In questions, \u2018Have you ever\u2026?\u2019 asks about experience; \u2018Did you\u2026?\u2019 asks about a known occasion.","American English often prefers the simple past where British English uses the perfect: \u2018Did you eat yet?\u2019 vs \u2018Have you eaten yet?\u2019"],
     examples:["Reporters have uncovered new evidence this week.","The story broke last night.","I\u2019ve never seen a headline like it."],
     watch:"Never combine the present perfect with a finished time: \u2018I have seen him yesterday\u2019 is wrong."},
    {name:"Present perfect vs. present perfect continuous", short:"Result and quantity, or activity and duration.",
     rule:"The simple form focuses on the completed result or how many; the continuous focuses on the activity itself and how long.",
     form:["Simple: has / have + p.p. \u2014 She has written three articles.","Continuous: has / have been + -ing \u2014 She has been writing since dawn.","Duration: for six months / since March \u2192 usually continuous."],
     notes:["State verbs (know, be, believe, own) are not normally used in the continuous.","The continuous can suggest the activity is unfinished, or that its effects are visible: \u2018She\u2019s been crying.\u2019","With \u2018how long\u2019, both are possible with live/work/study, with almost no difference in meaning."],
     examples:["She has written the report already.","She has been writing since dawn.","They\u2019ve been investigating the case for weeks."],
     watch:"Use the simple form when you say how many: \u2018I\u2019ve read three articles\u2019, not \u2018I\u2019ve been reading three articles\u2019."},
    {name:"Past perfect and time adverbs", short:"The earlier of two past events.",
     rule:"The past perfect (had + past participle) marks the event that happened first when you are already talking about the past. Adverbs like already, just, never and yet sit between the auxiliary and the participle.",
     form:["had + past participle: By the time we arrived, the crowd had already left.","Negative: He had never spoken to the press before.","With adverb: The editor had just finished when the news broke."],
     notes:["If the order of events is obvious from \u2018before\u2019 or \u2018after\u2019, the past perfect becomes optional.","\u2018Yet\u2019 goes at the end of negatives and questions; \u2018already\u2019 goes in mid-position.","In reported speech, a past simple in the original usually shifts to the past perfect."],
     examples:["By the time we arrived, the crowd had already left.","He had never spoken to the press before that morning.","The editor had just finished when the news broke."],
     watch:"Only one past perfect is needed to set the scene \u2014 the rest of the narrative can stay in the simple past."} ],
  speaking:[
    {kind:"Role-play", text:"A journalist interviews an eyewitness, trying to get to the bottom of a confusing story."},
    {kind:"Debate", text:"This house believes the media blows most stories out of proportion. Agree or disagree."},
    {kind:"Pair work", text:"Tell a partner about a rumour you once heard \u2013 what have you found out since?"} ],
  tips:[
    "Use the present perfect (not the past simple) with \u2018just, already, yet, ever, never\u2019.",
    "The present perfect continuous stresses duration or that an activity is unfinished.",
    "Common slip: \u2018I\u2019ve lived here for five years\u2019 (still here) vs \u2018I lived there for five years\u2019 (finished)."],
  quiz:{q:"Investigators ___ working on the case for months.", options:["have been","have","are been"], answer:0, explain:"Present perfect continuous (\u2018have been + -ing\u2019) stresses an ongoing activity over time."} },

{ n:7, title:"THE INFORMATION AGE", classes:"43\u201349", level:"The Tag-Question Redstone Lab", icon:"redstone", color:"#cf3a2f", theme:"Opinions about technology and its regulation",
  overview:{
    intro:"Giving an opinion in English is rarely a flat statement \u2014 it is an invitation. Tag questions and negative questions let you state a view while checking whether the other person shares it, which is exactly what a good discussion needs.",
    goals:["Discuss technology, privacy and information overload with current vocabulary.","Form tag questions correctly, including the tricky auxiliaries.","Use negative questions to soften opinions or express surprise.","Choose between active and passive to hide the agent or emphasise it."],
    outcome:"By the end you can hold a three-minute discussion about technology using at least four tag questions to invite agreement."
  },
  vocab:[
    {term:"to keep up with", pos:"phrasal verb", def:"to stay informed about, or move at the same pace as, something.",
     use:"Three parts, so never separable: keep up with the news, keep up with them.",
     examples:["It\u2019s impossible to keep up with every new app.","She struggles to keep up with the rest of the class."],
     colloc:"keep up with the news \u00b7 keep up with technology \u00b7 hard to keep up with"},
    {term:"data privacy", pos:"noun phrase", def:"the protection of personal information online.",
     use:"Uncountable. Common in debates about regulation: data privacy laws, data privacy concerns.",
     examples:["Data privacy is the main worry for most users.","New data privacy rules take effect in January."],
     colloc:"data privacy laws \u00b7 data privacy concerns \u00b7 protect data privacy"},
    {term:"overwhelming", pos:"adjective", def:"too much to deal with; intensely strong.",
     use:"Two senses: too much (an overwhelming amount) and very strong (overwhelming support). Context decides.",
     examples:["The amount of information online is overwhelming.","There was overwhelming support for the ban."],
     colloc:"overwhelming amount \u00b7 overwhelming majority \u00b7 feel overwhelmed"},
    {term:"to log off", pos:"phrasal verb", def:"to disconnect from a device or account.",
     use:"Also used figuratively for stepping away from the internet entirely. Opposite: log in / log on.",
     examples:["I try to log off completely at weekends.","Remember to log off on shared computers."],
     colloc:"log off for the day \u00b7 log off social media"},
    {term:"misinformation", pos:"noun", def:"false information that is spread, often unintentionally.",
     use:"Uncountable. Compare \u2018disinformation\u2019, which is false information spread deliberately.",
     examples:["Most misinformation spreads because people share without reading.","Platforms are under pressure to label misinformation."],
     colloc:"spread misinformation \u00b7 tackle misinformation \u00b7 online misinformation"},
    {term:"addictive", pos:"adjective", def:"causing a strong urge to keep doing something.",
     use:"Describes the thing; the person is \u2018addicted to\u2019 it. Note the preposition \u2018to\u2019 + noun or -ing.",
     examples:["These apps are deliberately addictive.","He\u2019s addicted to checking his notifications."],
     colloc:"highly addictive \u00b7 addicted to something \u00b7 an addictive design"} ],
  grammar:[
    {name:"Tag questions", short:"It\u2019s addictive, isn\u2019t it?",
     rule:"A tag question is a short question added to a statement to invite agreement or confirm information. A positive statement takes a negative tag; a negative statement takes a positive tag.",
     form:["Positive \u2192 negative tag: Technology moves fast, doesn\u2019t it?","Negative \u2192 positive tag: You haven\u2019t logged off, have you?","The tag repeats the auxiliary; with no auxiliary, use do / does / did."],
     notes:["The pronoun in the tag matches the subject: \u2018Your phone is old, isn\u2019t it?\u2019","Falling intonation on the tag means you expect agreement; rising intonation makes it a genuine question.","Special cases: \u2018I\u2019m right, aren\u2019t I?\u2019, \u2018Let\u2019s go, shall we?\u2019, \u2018Open the window, will you?\u2019"],
     examples:["Technology moves fast, doesn\u2019t it?","You\u2019ve seen the new update, haven\u2019t you?","Nobody reads the terms, do they?"],
     watch:"Match the tag to the auxiliary, not to the meaning: \u2018This app collects data, doesn\u2019t it?\u2019 \u2014 not \u2018isn\u2019t it?\u2019"},
    {name:"Negative questions for opinions", short:"Isn\u2019t it worrying how much they collect?",
     rule:"A negative question is not really asking for information. It either expresses surprise, invites agreement, or softens a strong opinion into something more sociable.",
     form:["Isn\u2019t it + adjective + clause: Isn\u2019t it amazing how fast things change?","Don\u2019t you think + clause: Don\u2019t you think we should log off more?","Haven\u2019t / Didn\u2019t + subject: Haven\u2019t you read the privacy policy?"],
     notes:["Answering can be confusing: \u2018Don\u2019t you agree?\u2019 \u2014 \u2018Yes\u2019 means you do agree.","Used with strong stress, a negative question can sound like criticism: \u2018Didn\u2019t you check?\u2019","The contracted form is far more natural in speech than \u2018Do you not think\u2026?\u2019, which sounds formal or annoyed."],
     examples:["Isn\u2019t it worrying how much data they collect?","Don\u2019t you think children get phones too early?","Haven\u2019t we all shared something without checking it?"],
     watch:"Use the contraction at the front \u2014 \u2018Isn\u2019t it\u2026?\u2019, not \u2018Is not it\u2026?\u2019"},
    {name:"Passive of present continuous, present perfect, future", short:"Hide the agent, or bring it back for emphasis.",
     rule:"If the agent (the person or thing doing the action) is unknown or obvious from the context, it’s better to use a passive form. However, if the person or thing doing the action needs to be emphasized, it’s better to use an active form.",
     form:["Present continuous passive: am / is / are + being + past participle — The spyware is being used to collect information.","Present perfect passive: have / has + been + past participle — Social networking sites have been used in criminal investigations.","Future passive: will be / is going to be + past participle — The new privacy rules will be announced next month."],
     notes:["The passive is very rarely used with the present perfect continuous. Use the passive of the present perfect instead: ‘More videos have been posted to the Internet this year than ever before.’","Keep the active when the agent is the news: ‘A criminal organization has created this virus, not an amateur hacker.’","Add ‘by + agent’ only when the agent is new or surprising information — otherwise leave it out completely.","In the future passive, only ‘be’ changes: will be collected, is going to be collected, will have been collected."],
     examples:["The spyware is being used to collect information about college students. (Agent is unknown.)","Social networking sites have been used in criminal investigations. (Agent is clear from context.)","A criminal organization has created this virus, not an amateur hacker. (Agent is emphasized.)","People have been posting more videos to the Internet this year than ever before. → More videos have been posted to the Internet this year than ever before.","Millions of accounts are going to be checked before the new rules take effect."],
     watch:"Never write ‘have been being posted’ — the present perfect continuous has no natural passive. Use the present perfect passive.",
     deep:"The passive is not a politeness device and not a way of sounding academic; it is a way of choosing what the sentence starts with. English sentences put the known, the given or the topic first, so when the agent is unknown, irrelevant or already obvious, the passive lets the affected thing take the subject position: ‘The spyware is being used to collect information.’ Nobody knows who wrote the spyware, and the sentence does not pretend otherwise. When the agent is the point — the whole reason the sentence exists — the active form must come back, which is why ‘A criminal organization has created this virus, not an amateur hacker’ cannot be passive without losing its argument. Mechanically, each tense keeps its own auxiliaries and adds ‘be’ plus the past participle: the present continuous inserts ‘being’ (is being used), the present perfect inserts ‘been’ (has been used), and future forms simply add ‘be’ after the future marker (will be used, is going to be used). The one gap in the system is the present perfect continuous: ‘has been being used’ is grammatically derivable but nobody says it, so English uses the present perfect passive instead and lets the context supply the sense of ongoing activity. In writing about technology, research and regulation, this pattern does most of the work: processes and data take the subject position, and the agent appears only when naming it changes the reader’s conclusion.",
     chart:{title:"Passive across the tenses", cols:["Tense","Passive form","Example"], rows:[["Present continuous","am / is / are + being + p.p.","The spyware is being used to collect data."],["Present perfect","have / has + been + p.p.","Two accounts have been suspended today."],["Future – will","will be + p.p.","The report will be published on Monday."],["Future – going to","is / are going to be + p.p.","New rules are going to be introduced."],["Future perfect","will have been + p.p.","By June the app will have been removed."],["Present perfect continuous","avoid — use the present perfect passive","More videos have been posted than ever before."],["Agent","by + agent, only when it is news","This virus was created by a criminal organization."]]}} ],
  speaking:[
    {kind:"Role-play", text:"Two friends argue about whether children should have smartphones \u2013 use tag questions to seek agreement."},
    {kind:"Debate", text:"This house believes social media should be regulated like other media. Argue for or against."},
    {kind:"Pair work", text:"Ask your partner three tag questions about their tech habits, then react to the answers."} ],
  tips:[
    "A positive statement takes a negative tag, and vice versa: \u2018It works, doesn\u2019t it?\u2019 / \u2018It doesn\u2019t work, does it?\u2019",
    "The tag repeats the auxiliary; if there\u2019s none, use \u2018do / does / did\u2019.",
    "Common slip: the tag for \u2018I am\u2019 is \u2018aren\u2019t I?\u2019 \u2013 \u2018I\u2019m right, aren\u2019t I?\u2019"],
  quiz:{q:"This app collects a lot of data, ___?", options:["doesn\u2019t it","does it","isn\u2019t it"], answer:0, explain:"A positive statement with \u2018collects\u2019 takes the negative tag \u2018doesn\u2019t it\u2019."} },

{ n:8, title:"PUTTING THE MIND TO WORK", classes:"50\u201356", level:"The Reduced-Relative Enchantment", icon:"amethyst", color:"#7a4fb0", theme:"Psychology, memory and how the brain works",
  overview:{
    intro:"Writing about how the mind works means packing information densely. Reduced relative clauses let you cut words without losing meaning, and sentence-modifying \u2018which\u2019 lets you comment on a whole idea \u2014 both are hallmarks of B2 writing.",
    goals:["Talk about memory, forgetting and mental effort with idiomatic language.","Shorten relative clauses by removing the pronoun and \u2018be\u2019.","Comment on a whole clause using non-defining \u2018, which\u2026\u2019."],
    outcome:"By the end you can explain a memory technique in writing, using two reduced relative clauses and one sentence-modifying \u2018which\u2019."
  },
  vocab:[
    {term:"to slip one\u2019s mind", pos:"idiom", def:"to be forgotten.",
     use:"The forgotten thing is the subject: \u2018It slipped my mind\u2019, not \u2018I slipped my mind\u2019. A soft, polite excuse.",
     examples:["Sorry, your birthday completely slipped my mind.","The appointment slipped his mind until the reminder arrived."],
     colloc:"it slipped my mind \u00b7 completely slip your mind"},
    {term:"to rack one\u2019s brains", pos:"idiom", def:"to think very hard to remember or solve something.",
     use:"Often followed by \u2018trying to\u2019 or \u2018for\u2019: racking my brains for a name.",
     examples:["I racked my brains but couldn\u2019t remember where we\u2019d met.","We racked our brains trying to solve the last clue."],
     colloc:"rack your brains for something \u00b7 rack your brains trying to\u2026"},
    {term:"vivid", pos:"adjective", def:"producing powerful, clear images in the mind.",
     use:"Used of memories, dreams, descriptions and colours. Strongly positive when describing writing.",
     examples:["I have a vivid memory of my first day at school.","She gave a vivid description of the accident."],
     colloc:"a vivid memory \u00b7 a vivid dream \u00b7 vivid detail"},
    {term:"to jog one\u2019s memory", pos:"idiom", def:"to help someone remember something.",
     use:"Something external does the jogging: a photo, a smell, a question.",
     examples:["Maybe this photo will jog your memory.","He mentioned the hotel name to jog my memory."],
     colloc:"jog someone\u2019s memory \u00b7 something to jog your memory"},
    {term:"absent-minded", pos:"adjective", def:"forgetful because your thoughts are elsewhere.",
     use:"Gentle and often affectionate \u2014 it suggests a thinker, not a careless person.",
     examples:["My absent-minded uncle once left the car keys in the fridge.","I\u2019ve been so absent-minded this week."],
     colloc:"an absent-minded professor \u00b7 rather absent-minded"},
    {term:"to sink in", pos:"phrasal verb", def:"(of information) to be fully understood or realised.",
     use:"Intransitive and always about news or facts, usually with a delay: \u2018It hasn\u2019t sunk in yet.\u2019",
     examples:["It took a day for the news to sink in.","I heard the result, but it still hasn\u2019t sunk in."],
     colloc:"take time to sink in \u00b7 hasn\u2019t sunk in yet \u00b7 slowly sink in"} ],
  grammar:[
    {name:"Reduced relative clauses", short:"the woman who is standing \u2192 the woman standing.",
     rule:"When a relative clause contains a form of \u2018be\u2019, you can delete the relative pronoun and \u2018be\u2019 together. When it contains an active verb, you can replace the pronoun and verb with an -ing form.",
     form:["Active \u2192 -ing: The people who were waiting outside \u2192 the people waiting outside.","Passive \u2192 past participle: The study that was published \u2192 the study published.","With a general subject: Anyone who wants to join \u2192 anyone wanting to join."],
     notes:["Only defining relative clauses are normally reduced in everyday English.","A reduced clause keeps its position immediately after the noun it describes.","The reduction works only when the relative pronoun is the SUBJECT of the clause \u2014 \u2018the book that I read\u2019 cannot become \u2018the book reading\u2019."],
     examples:["The people waiting outside were all volunteers.","The technique used by the researchers is surprisingly simple.","Anyone wanting to join should sign up today."],
     watch:"Never reduce when the pronoun is the object of the clause \u2014 it changes who is doing the action."},
    {name:"Sentence-modifying \u2018which\u2019", short:"He forgot my name, which was embarrassing.",
     rule:"After a comma, \u2018which\u2019 can refer back to the whole preceding idea rather than to a single noun, letting you add a comment or reaction.",
     form:[", which + verb + comment: She solved it in seconds, which impressed everyone.",", which is / was + adjective: He forgot my name, which was embarrassing.","Can end the sentence: They cancelled the study, which surprised no one."],
     notes:["The comma is obligatory \u2014 without it, \u2018which\u2019 seems to refer only to the nearest noun.","This structure is a favourite in written commentary and reviews.","It cannot start a new sentence in formal writing: join it to the clause it comments on."],
     examples:["She solved it in seconds, which impressed everyone.","They cancelled the study, which surprised no one.","He remembered every detail, which is unusual after so long."],
     watch:"Use \u2018, which\u2019, never \u2018what\u2019 or \u2018that\u2019, to comment on a whole clause."} ],
  speaking:[
    {kind:"Role-play", text:"A memory trainer teaches a client a technique \u2013 explain the steps and answer their questions."},
    {kind:"Debate", text:"This house believes we rely on our phones too much and it\u2019s ruining our memory. Agree or disagree."},
    {kind:"Pair work", text:"Share a memory trick you use, then describe a time something completely slipped your mind."} ],
  tips:[
    "You can reduce a relative clause when it contains a form of \u2018be\u2019 or an active -ing action.",
    "Sentence-modifying \u2018which\u2019 always follows a comma and refers to the whole previous idea.",
    "Common slip: don\u2019t use \u2018what\u2019 to comment on a whole clause \u2013 use \u2018, which\u2019."],
  quiz:{q:"The results, ___ surprised the whole team, were published today.", options:["which","that","what"], answer:0, explain:"A non-defining clause commenting on the whole idea uses \u2018, which\u2019."} },

{ n:9, title:"GENERALLY SPEAKING", classes:"57\u201363", level:"The Used-To Hay Fields", icon:"hay", color:"#b5891a", theme:"Cultural generalisations and childhood habits",
  overview:{
    intro:"Talking about cultures means generalising \u2014 and generalising safely means signalling the exceptions. This unit gives you contrast structures for comparing groups, and the two past-habit forms for describing how things used to be.",
    goals:["Discuss customs, norms and stereotypes without overgeneralising.","Contrast and except with unlike, while, whereas and except that.","Describe past habits and states with \u2018used to\u2019 and \u2018would\u2019."],
    outcome:"By the end you can compare two cultures you know using three contrast structures, and describe how your own habits used to be different."
  },
  vocab:[
    {term:"stereotype", pos:"noun", def:"an oversimplified, fixed idea about a group of people.",
     use:"Nearly always negative. As a verb: \u2018to stereotype someone\u2019. The adjective is \u2018stereotypical\u2019.",
     examples:["The film relies on tired national stereotypes.","It\u2019s unfair to stereotype an entire generation."],
     colloc:"a common stereotype \u00b7 challenge a stereotype \u00b7 stereotypical behaviour"},
    {term:"to generalise", pos:"verb", def:"to make a broad statement that may not fit every case.",
     use:"Often self-critical: \u2018I\u2019m generalising, but\u2026\u2019 \u2014 a useful hedge in a debate.",
     examples:["I\u2019m generalising, but people here tend to eat later.","It\u2019s risky to generalise from a single visit."],
     colloc:"generalise about something \u00b7 a sweeping generalisation"},
    {term:"norm", pos:"noun", def:"a standard or typical pattern of behaviour in a society.",
     use:"Countable (social norms) and also in the phrase \u2018the norm\u2019 meaning the usual thing.",
     examples:["Working from home has become the norm here.","Social norms around punctuality vary enormously."],
     colloc:"social norms \u00b7 cultural norms \u00b7 become the norm"},
    {term:"upbringing", pos:"noun", def:"the way a person is raised as a child.",
     use:"Almost always singular with a possessive: my upbringing, a strict upbringing.",
     examples:["She had a very strict upbringing in a small town.","My upbringing taught me to greet everyone in the room."],
     colloc:"a strict / religious / traditional upbringing"},
    {term:"to fit in", pos:"phrasal verb", def:"to feel accepted and comfortable within a group.",
     use:"Use \u2018with\u2019 for the group: fit in with the others. Not separable.",
     examples:["It took a year to fit in at my new school.","He never quite fitted in with the rest of the team."],
     colloc:"fit in with a group \u00b7 struggle to fit in \u00b7 fit right in"},
    {term:"customs", pos:"noun (plural)", def:"traditional ways of behaving in a particular culture.",
     use:"In the plural for traditions; the singular \u2018customs\u2019 at an airport is a different word entirely.",
     examples:["Local customs vary from one region to the next.","It\u2019s polite to learn a few customs before you travel."],
     colloc:"local customs \u00b7 traditional customs \u00b7 respect the customs"} ],
  grammar:[
    {name:"Contrast and exception", short:"unlike / while / whereas / except that.",
     rule:"These structures set two ideas against each other. Choosing the right one depends on whether you are contrasting nouns, contrasting whole clauses, or noting a single exception.",
     form:["unlike + noun: Unlike my brother, I love mornings.","while / whereas + clause: While some cultures value punctuality, others are more relaxed.","except (that) + clause / except for + noun: It\u2019s a great city, except that it rains a lot."],
     notes:["\u2018Whereas\u2019 is more formal than \u2018while\u2019 and only ever means contrast \u2014 \u2018while\u2019 can also mean \u2018during\u2019.","\u2018Unlike\u2019 must be followed by a noun or pronoun, never a clause.","\u2018Except for\u2019 introduces the one thing that spoils an otherwise complete statement."],
     examples:["Unlike my brother, I love getting up early.","While some cultures value punctuality, others are far more relaxed.","The trip was perfect, except for the flight home."],
     watch:"To contrast two full clauses use \u2018while\u2019 or \u2018whereas\u2019 \u2014 \u2018unlike\u2019 only compares nouns."},
    {name:"Past habits: used to and would", short:"States take \u2018used to\u2019; repeated actions take either.",
     rule:"\u2018Used to\u2019 describes past states and repeated actions that are no longer true. \u2018Would\u2019 describes repeated past actions only \u2014 never states.",
     form:["used to + base verb: We used to live in a small town.","would + base verb: Every summer, my grandmother would tell us stories.","Negative and question: didn\u2019t use to \u00b7 Did you use to\u2026?"],
     notes:["States (be, have, know, live, like) work only with \u2018used to\u2019: \u2018I used to be shy\u2019, not \u2018I would be shy\u2019.","\u2018Would\u2019 needs a past time frame already established, which is why it is common in storytelling.","Don\u2019t confuse \u2018used to do\u2019 (past habit) with \u2018be used to doing\u2019 (be accustomed to)."],
     examples:["We used to live by the sea.","Every summer, my grandmother would tell us the same story.","I didn\u2019t use to like coffee at all."],
     watch:"In negatives and questions the \u2018d\u2019 disappears: \u2018Did you use to\u2026?\u2019, not \u2018Did you used to\u2026?\u2019"} ],
  speaking:[
    {kind:"Role-play", text:"Two travellers compare culture-shock stories from different countries they\u2019ve visited."},
    {kind:"Debate", text:"This house believes stereotypes always contain a grain of truth. Agree or disagree."},
    {kind:"Pair work", text:"Describe a childhood habit using \u2018used to\u2019 and \u2018would\u2019 \u2013 and whether you\u2019ve grown out of it."} ],
  tips:[
    "Use \u2018would\u2019 for repeated past actions, but \u2018used to\u2019 for past states: \u2018I used to be shy\u2019, not \u2018I would be shy\u2019.",
    "In the negative and question, drop the -d: \u2018didn\u2019t use to\u2019, \u2018Did you use to\u2026?\u2019",
    "Common slip: \u2018unlike\u2019 compares nouns; to contrast whole clauses use \u2018while\u2019 or \u2018whereas\u2019."],
  quiz:{q:"When I was a child, we ___ live by the sea.", options:["used to","would","use to"], answer:0, explain:"For a past state (living somewhere), use \u2018used to\u2019, not \u2018would\u2019."} },

{ n:10, title:"THE ART OF COMPLAINING", classes:"64\u201370", level:"The Indirect-Question TNT Mines", icon:"tnt", color:"#d64533", theme:"Everyday annoyances and diplomatic complaining",
  overview:{
    intro:"Complaining in a second language is risky: too soft and nothing happens, too direct and you sound aggressive. Indirect questions and noun clauses give you the distance that English politeness relies on.",
    goals:["Describe faults, annoyances and solutions with the right register.","Use noun clauses as subjects and objects.","Form simple and complex indirect questions with statement word order."],
    outcome:"By the end you can make a full complaint and request a solution using at least three indirect questions."
  },
  vocab:[
    {term:"to have a bone to pick with", pos:"idiom", def:"to have a reason to complain to someone.",
     use:"Semi-humorous and personal \u2014 used with people you know, not with a shop assistant.",
     examples:["I\u2019ve got a bone to pick with you about last night.","She had a bone to pick with her landlord."],
     colloc:"have a bone to pick with someone"},
    {term:"faulty", pos:"adjective", def:"not working correctly; defective.",
     use:"Standard word for consumer complaints. For a service, use \u2018poor\u2019; for reasoning, \u2018flawed\u2019.",
     examples:["The charger was faulty from the first day.","We\u2019re recalling faulty units free of charge."],
     colloc:"a faulty product \u00b7 faulty wiring \u00b7 return a faulty item"},
    {term:"refund", pos:"noun / verb", def:"money returned to you when you take a product back.",
     use:"As a noun with \u2018get / give / ask for\u2019; as a verb, \u2018they refunded the money\u2019. Compare \u2018exchange\u2019.",
     examples:["I\u2019d like a full refund rather than a replacement.","They refunded me within three days."],
     colloc:"a full refund \u00b7 ask for a refund \u00b7 a no-refund policy"},
    {term:"to put up with", pos:"phrasal verb", def:"to tolerate something unpleasant without complaining.",
     use:"Three parts, never separable: put up with it. The formal equivalent is \u2018tolerate\u2019.",
     examples:["I\u2019m not putting up with that noise another night.","She put up with the situation for years."],
     colloc:"put up with noise \u00b7 have to put up with \u00b7 refuse to put up with"},
    {term:"to make a fuss", pos:"idiom", def:"to complain or worry more than a situation deserves.",
     use:"Often used to describe someone else\u2019s reaction, or to excuse your own: \u2018I don\u2019t want to make a fuss, but\u2026\u2019",
     examples:["I don\u2019t want to make a fuss, but this isn\u2019t what I ordered.","He made a huge fuss about a five-minute delay."],
     colloc:"make a fuss about something \u00b7 without making a fuss"},
    {term:"the last straw", pos:"idiom", def:"the final small problem that makes a situation unbearable.",
     use:"Refers to something minor in itself \u2014 that is the point of the idiom.",
     examples:["The cancelled flight was the last straw.","When they lost my order again, that was the last straw."],
     colloc:"the last straw \u00b7 the final straw"} ],
  grammar:[
    {name:"Noun clauses and relative clauses", short:"What annoys me is\u2026 / the item that broke.",
     rule:"A noun clause does the job of a noun \u2014 subject or object of the sentence. A relative clause does the job of an adjective, describing a noun that is already there.",
     form:["Noun clause as subject: What annoys me is the noise.","Noun clause as object: I don\u2019t understand why they charged me twice.","Relative clause: The product that I bought is faulty."],
     notes:["Noun clauses keep statement word order even when they start with a question word.","\u2018What\u2019 in a noun clause means \u2018the thing that\u2019 \u2014 don\u2019t add \u2018that\u2019 as well.","A noun-clause subject takes a singular verb: \u2018What worries me is the delays.\u2019"],
     examples:["What annoys me most is the constant noise.","The product that I bought last week is already faulty.","I don\u2019t understand why they charged me twice."],
     watch:"Don\u2019t write \u2018What that annoys me\u2026\u2019 \u2014 \u2018what\u2019 already contains \u2018the thing that\u2019."},
    {name:"Indirect questions", short:"Could you tell me where the manager is?",
     rule:"An indirect question wraps a question inside a polite introductory phrase. The inner question loses its inversion and its auxiliary \u2018do\u2019.",
     form:["Introductory phrase + question word + subject + verb: Could you tell me where the fitting rooms are?","With no question word, use if / whether: Do you know if this is refundable?","Common openers: Could you tell me\u2026 \u00b7 Do you know\u2026 \u00b7 I was wondering\u2026 \u00b7 Would you mind telling me\u2026"],
     notes:["Delete \u2018do / does / did\u2019 completely: \u2018I wonder what it costs\u2019, not \u2018what does it cost\u2019.","If the sentence starts with \u2018Could you\u2026\u2019 it takes a question mark; if it starts with \u2018I was wondering\u2026\u2019 it takes a full stop.","\u2018Whether\u2019 is slightly more formal than \u2018if\u2019 and is the only option before \u2018or not\u2019."],
     examples:["Could you tell me when it will be fixed?","Do you know if this is refundable?","I was wondering whether you could help me with a return."],
     watch:"Statement word order inside: \u2018where the manager is\u2019, never \u2018where is the manager\u2019."} ],
  speaking:[
    {kind:"Role-play", text:"A customer returns a faulty product to a shop assistant \u2013 complain politely and reach a solution."},
    {kind:"Debate", text:"This house believes people complain far too much these days. Agree or disagree."},
    {kind:"Pair work", text:"Turn three blunt complaints into polite, indirect ones with your partner."} ],
  tips:[
    "Indirect questions use statement word order: \u2018Could you tell me where it is?\u2019 (not \u2018where is it\u2019).",
    "Use \u2018if\u2019 or \u2018whether\u2019 when there\u2019s no question word: \u2018Do you know if it\u2019s open?\u2019",
    "Common slip: drop \u2018do / does / did\u2019 in an indirect question \u2013 \u2018I wonder what it costs\u2019, not \u2018what does it cost\u2019."],
  quiz:{q:"Could you tell me where ___?", options:["the fitting rooms are","are the fitting rooms","do the fitting rooms are"], answer:0, explain:"Indirect questions use statement word order: \u2018where the fitting rooms are\u2019."} },

{ n:11, title:"VALUES", classes:"71\u201377", level:"The Conditional Heart Vault", icon:"heart", color:"#caa11c", theme:"Ethics, hypothetical situations, wishes and regrets",
  overview:{
    intro:"Ethical discussion is hypothetical by nature: what would you do, what if nobody found out, what do you wish you had done? This unit builds the unreal conditional and the language of regret so you can argue about values, not just describe them.",
    goals:["Discuss honesty, principles and dilemmas with precise vocabulary.","Use the present unreal conditional, including unless, only if and even if.","Express present wishes and past regrets accurately."],
    outcome:"By the end you can argue a moral dilemma using three unreal conditionals and express one regret with \u2018if only\u2019."
  },
  vocab:[
    {term:"integrity", pos:"noun", def:"the quality of being honest and having strong moral principles.",
     use:"Uncountable and always positive. Common in references and job descriptions.",
     examples:["She\u2019s a leader of real integrity.","The scandal damaged the company\u2019s integrity."],
     colloc:"personal / professional integrity \u00b7 a person of integrity"},
    {term:"to stand up for", pos:"phrasal verb", def:"to defend a person or a belief.",
     use:"Three parts, inseparable. \u2018Stand up to\u2019 is different \u2014 it means resist someone powerful.",
     examples:["He stood up for a colleague nobody else would defend.","Stand up for what you believe, even alone."],
     colloc:"stand up for yourself \u00b7 stand up for your beliefs"},
    {term:"dilemma", pos:"noun", def:"a difficult choice between two options, often both unattractive.",
     use:"Strictly two options \u2014 that is what \u2018di-\u2019 means. Use \u2018difficult decision\u2019 for more.",
     examples:["She faced a real dilemma: tell the truth or protect her friend.","It\u2019s an ethical dilemma with no easy answer."],
     colloc:"face a dilemma \u00b7 an ethical / moral dilemma"},
    {term:"to have second thoughts", pos:"idiom", def:"to begin to doubt a decision you have made.",
     use:"Takes \u2018about\u2019: second thoughts about the job. Implies the decision was already taken.",
     examples:["I\u2019m having second thoughts about accepting the offer.","He signed, then had second thoughts overnight."],
     colloc:"have second thoughts about something \u00b7 serious second thoughts"},
    {term:"principled", pos:"adjective", def:"acting on firm moral rules.",
     use:"A compliment; \u2018unprincipled\u2019 is a strong insult. Compare \u2018stubborn\u2019, which is negative.",
     examples:["It was a principled decision that cost him the job.","She\u2019s too principled to accept the gift."],
     colloc:"a principled stand \u00b7 highly principled"},
    {term:"to draw the line", pos:"idiom", def:"to set a limit on what you will accept or do.",
     use:"Takes \u2018at\u2019 for the limit: \u2018I draw the line at lying.\u2019",
     examples:["I\u2019ll bend the rules, but I draw the line at lying.","Everyone has to draw the line somewhere."],
     colloc:"draw the line at something \u00b7 draw a clear line"} ],
  grammar:[
    {name:"Present unreal conditional", short:"If + past, would + verb \u2014 plus unless, only if, even if.",
     rule:"To imagine a present or future situation that is not real, use a past form in the if-clause and \u2018would\u2019 in the result clause. The past tense signals distance from reality, not past time.",
     form:["If + past simple, would + base verb: If I had more time, I\u2019d volunteer.","unless = if\u2026 not: I wouldn\u2019t lie unless I had to.","only if = on this single condition \u00b7 even if = whether or not: Even if they offered me a fortune, I\u2019d refuse."],
     notes:["\u2018Were\u2019 is used for all persons in careful English: \u2018If I were you\u2026\u2019.","\u2018Could\u2019 and \u2018might\u2019 can replace \u2018would\u2019 to weaken the result: \u2018I might tell him.\u2019","When \u2018only if\u2019 starts the sentence, the main clause inverts: \u2018Only if he apologised would I forgive him.\u2019"],
     examples:["If I were you, I\u2019d tell the truth straight away.","I wouldn\u2019t lie unless I absolutely had to.","Even if nobody ever found out, I\u2019d still feel guilty."],
     watch:"Keep \u2018would\u2019 out of the if-clause: \u2018If I had time\u2026\u2019, not \u2018If I would have time\u2026\u2019"},
    {name:"Wishes and regrets", short:"wish + past / past perfect / would.",
     rule:"\u2018Wish\u2019 and \u2018if only\u2019 shift one tense back from the reality you are describing. The tense you choose shows whether you regret the present, the past, or someone else\u2019s behaviour.",
     form:["Present wish: wish + past simple \u2014 I wish I had more free time.","Past regret: wish + past perfect \u2014 If only I had said sorry.","Annoyance at others: wish + would \u2014 I wish people wouldn\u2019t drop litter."],
     notes:["\u2018If only\u2019 is simply a more emphatic \u2018I wish\u2019.","You cannot use \u2018wish + would\u2019 about yourself \u2014 use \u2018wish I could\u2019 instead.","\u2018I wish I were\u2026\u2019 is preferred to \u2018I wish I was\u2026\u2019 in formal English."],
     examples:["I wish I had more free time during the week.","If only I had said sorry when I had the chance.","I wish people wouldn\u2019t leave their rubbish behind."],
     watch:"\u2018Wish + past simple\u2019 = present wish; \u2018wish + past perfect\u2019 = past regret. Mixing them changes the meaning entirely."} ],
  speaking:[
    {kind:"Role-play", text:"Two friends find a lost wallet full of cash and argue over the right thing to do."},
    {kind:"Debate", text:"This house believes honesty is always the best policy. Argue for or against."},
    {kind:"Pair work", text:"Share a decision you have second thoughts about, using \u2018I wish\u2026\u2019 and \u2018If only\u2026\u2019."} ],
  tips:[
    "In the second conditional, use \u2018were\u2019 for all subjects: \u2018If I were rich\u2026\u2019.",
    "\u2018wish + past simple\u2019 = a present wish; \u2018wish + past perfect\u2019 = a past regret.",
    "Common slip: \u2018unless\u2019 already means \u2018if\u2026 not\u2019 \u2013 don\u2019t add another \u2018not\u2019."],
  quiz:{q:"I ___ take the money even if no one was watching.", options:["wouldn\u2019t","won\u2019t","don\u2019t"], answer:0, explain:"The present unreal conditional uses \u2018would(n\u2019t) + base verb\u2019: \u2018wouldn\u2019t take\u2019."} },

{ n:12, title:"MOVING AROUND", classes:"78\u201384", level:"The Mixed-Conditional End Portal", icon:"ender", color:"#52407f", theme:"Travel, culture shock and future life plans",
  overview:{
    intro:"The final unit looks forwards and backwards at once: what you will have achieved by a future date, and how a different past would have produced a different present. Mixed conditionals are the most advanced structure in the course \u2014 and the most satisfying to control.",
    goals:["Talk about relocating, culture shock and adaptation with natural vocabulary.","Use the future perfect and future perfect continuous with time markers.","Combine time frames in mixed conditional sentences."],
    outcome:"By the end you can describe your life five years from now with two future perfect sentences, and explain one turning point using a mixed conditional."
  },
  vocab:[
    {term:"culture shock", pos:"noun phrase", def:"the disorientation felt in an unfamiliar culture.",
     use:"Usually uncountable: \u2018I experienced culture shock.\u2019 Also \u2018reverse culture shock\u2019 on returning home.",
     examples:["The first month abroad was pure culture shock.","Nobody warns you about reverse culture shock."],
     colloc:"experience culture shock \u00b7 suffer from culture shock"},
    {term:"to settle in", pos:"phrasal verb", def:"to become comfortable in a new place or situation.",
     use:"Intransitive; takes time expressions: settle in quickly, take a while to settle in.",
     examples:["It took me six months to settle in properly.","They\u2019ve settled in well at the new school."],
     colloc:"settle in quickly \u00b7 take time to settle in"},
    {term:"homesick", pos:"adjective", def:"sad because you miss your home and family.",
     use:"Predicative: \u2018I felt homesick\u2019. The noun is \u2018homesickness\u2019.",
     examples:["I got terribly homesick during the first winter.","She was homesick for her mother\u2019s cooking."],
     colloc:"feel / get homesick \u00b7 homesick for somewhere"},
    {term:"to broaden one\u2019s horizons", pos:"idiom", def:"to gain wider knowledge and experience.",
     use:"Positive and slightly formal \u2014 common in motivation letters and interviews.",
     examples:["Living abroad broadened my horizons more than any course.","Reading widely broadens your horizons."],
     colloc:"broaden your horizons \u00b7 widen your horizons"},
    {term:"expat (expatriate)", pos:"noun", def:"a person living outside their native country.",
     use:"\u2018Expat\u2019 is the everyday short form. The word carries assumptions of choice, unlike \u2018immigrant\u2019 \u2014 worth discussing.",
     examples:["There\u2019s a large expat community in the city.","He\u2019s been an expat for over a decade."],
     colloc:"an expat community \u00b7 the expat life"},
    {term:"to get around", pos:"phrasal verb", def:"to travel from place to place within an area.",
     use:"Also means \u2018avoid\u2019 a rule (\u2018get around the regulations\u2019) \u2014 context makes it clear.",
     examples:["It\u2019s easy to get around by metro.","Without a car, getting around is a challenge."],
     colloc:"get around by bus \u00b7 easy to get around \u00b7 get around the city"} ],
  grammar:[
    {name:"Future perfect and future perfect continuous", short:"By 2030 I\u2019ll have finished / I\u2019ll have been living here for ten years.",
     rule:"The future perfect looks back from a point in the future: it describes an action completed before that point. The continuous form describes an activity still in progress up to it, stressing duration.",
     form:["will have + past participle: By next year, I\u2019ll have visited five countries.","will have been + -ing: By June, we\u2019ll have been travelling for six months.","Time markers: by then, by 2030, by the time\u2026, in two years."],
     notes:["A future time marker is essentially obligatory \u2014 without one the tense makes no sense.","After \u2018by the time\u2019, use the present tense, not \u2018will\u2019: \u2018by the time you arrive\u2019.","Use the continuous only with action verbs; \u2018will have known\u2019 stays simple."],
     examples:["By next year, I\u2019ll have visited five new countries.","By June, we\u2019ll have been travelling for six months.","They\u2019ll have settled in by the time you arrive."],
     watch:"\u2018By the time you WILL arrive\u2019 is wrong \u2014 time clauses stay in the present."},
    {name:"Mixed conditionals", short:"Past cause \u2192 present result, or present cause \u2192 past result.",
     rule:"A mixed conditional combines two different time frames in one sentence, because a past event can have a present consequence, and a permanent present fact can explain a past outcome.",
     form:["Past \u2192 present: If I had saved more, I\u2019d be travelling now.","Present \u2192 past: If I weren\u2019t so shy, I\u2019d have spoken up.","Structure: If + past perfect, would + base \u00b7 If + past simple, would have + p.p."],
     notes:["Look for a present time word (now, today, still) in the result to spot type one.","The if-clause with a present meaning usually describes a permanent characteristic.","Both halves remain hypothetical \u2014 neither actually happened."],
     examples:["If I had saved more last year, I\u2019d be travelling right now.","If she were more organised, she wouldn\u2019t have missed the flight.","If we\u2019d left earlier, we\u2019d be there by now."],
     watch:"Decide the time of each half separately \u2014 that decision alone tells you which forms to use."} ],
  speaking:[
    {kind:"Role-play", text:"An expat advises someone about to move abroad \u2013 cover culture shock and settling in."},
    {kind:"Debate", text:"This house believes living abroad is the best way to broaden your horizons. Argue for or against."},
    {kind:"Pair work", text:"Describe where you\u2019ll have travelled and what you\u2019ll have achieved five years from now."} ],
  tips:[
    "The future perfect needs a future time marker: \u2018by 2027\u2019, \u2018by the time\u2026\u2019, \u2018in two years\u2019.",
    "Mixed conditionals join a past \u2018if\u2019-clause with a present result, or the reverse.",
    "Common slip: after \u2018by the time\u2019 use the present, not the future: \u2018by the time you arrive\u2019, not \u2018will arrive\u2019."],
  quiz:{q:"By this time next year, I ___ my degree.", options:["will have finished","will finish","have finished"], answer:0, explain:"The future perfect (\u2018will have + past participle\u2019) describes an action completed by a future point."} }
];
